74	/// Find the Microsoft Edge executable on the current platform.
75	///
76	/// Does not verify whether the executable exists.
77	String findEdgeExecutable(Platform platform, FileSystem fileSystem) {
78	  if (platform.environment.containsKey(kEdgeEnvironment)) {
79	    return platform.environment[kEdgeEnvironment];
80	  }
81	  if (platform.isWindows) {
82	    /// The possible locations where the Edge executable can be located on windows.
83	    final List<String> kWindowsPrefixes = <String>[
84	      platform.environment['LOCALAPPDATA'],
85	      platform.environment['PROGRAMFILES'],
86	      platform.environment['PROGRAMFILES(X86)'],
87	    ];
88	    final String windowsPrefix = kWindowsPrefixes.firstWhere((String prefix) {
89	      if (prefix == null) {
90	        return false;
91	      }
92	      final String path = fileSystem.path.join(prefix, kWindowsEdgeExecutable);
93	      return fileSystem.file(path).existsSync();
94	    }, orElse: () => '.');
95	    return fileSystem.path.join(windowsPrefix, kWindowsEdgeExecutable);
96	  }
